-- Equipment serial number
--
-- MANUAL MIGRATION - apply deliberately (review, back up, then run).
-- Idempotent: safe to re-run.
--
-- Adds core."Equipment"."serialNumber" and the per-project uniqueness rule.
-- The serial is generated by the ROOT-only registration endpoint:
--   serialNumber = numeric(project.code) * 1,000,000 + per-project sequence
-- Legacy / imported equipment stays NULL; NULLs are exempt from the unique
-- index (standard Postgres/SQLite behavior).

BEGIN;

ALTER TABLE core."Equipment" ADD COLUMN IF NOT EXISTS "serialNumber" INTEGER;

CREATE UNIQUE INDEX IF NOT EXISTS "Equipment_projectId_serialNumber_key"
  ON core."Equipment" ("projectId", "serialNumber");

COMMIT;
